contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint ticketAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (ticketAmount)); require(ticketAmount <= 1000000000000000000000000000000);
        require(ticketAmount == 10);
        require(address(this).balance >= ticketAmount);

        bool reverted;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;

        c.play{value: ticketAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;

        assert(
            reverted ||
            (potBefore == 0
                ? (potAfter == 0 || potAfter == ticketAmount)
                : (potAfter == 0 || potAfter == potBefore + ticketAmount))
        );
    }

    receive() external payable {}
}

